  key(){return `${this.playerCards.join(",")}|${this.aiCards.join(",")}|${this.prizes().join(",")}|${this.currentPrize()}`;}
  policy(){const entry=GOOFSPIEL_POLICY[this.key()];if(!entry)throw new Error("missing exact Goofspiel policy state");return entry;}
